@dataclass
class ReferenceNode:
    node_id: str
    pinned: dict
    policy: object
    executor: object
    clock: object
    window: ConfirmationWindowDouble | None = None
    catalogue: list | None = None
    read_outputs: dict = field(default_factory=lambda: dict(DEFAULT_READ_OUTPUTS))
